function operation_dronagiri_data_submission_app_insert(&$error_message = '') {
	global $Translation;

	// mm: can member insert record?
	$arrPerm = getTablePermissions('operation_dronagiri_data_submission_app');
	if(!$arrPerm['insert']) {
		$error_message = $Translation['no insert permission'];
		return false;
	}

	$data = [
		'name_of_the_department' => br2nl(Request::val('name_of_the_department', '')),
		'name_of_the_officer' => Request::val('name_of_the_officer', ''),
		'designation' => Request::val('designation', ''),
		'email_address' => Request::val('email_address', ''),
		'phone_number' => Request::val('phone_number', ''),
		'submit_date' => parseCode('<%%creationDate%%> : <%%creationTime%%>', true, true),
		'created_by' => parseCode('<%%creatorUsername%%>', true),
		'created_at' => parseCode('<%%creationDateTime%%>', true),
	];

	// record owner is current user
	$recordOwner = getLoggedMemberID();

	$recID = tableInsert('operation_dronagiri_data_submission_app', $data, $recordOwner, $error_message);

	// if this record is a copy of another record, copy children if applicable
	if(strlen(Request::val('SelectedID')) && $recID !== false)
		operation_dronagiri_data_submission_app_copy_children($recID, Request::val('SelectedID'));

	return $recID;
}

