function operation_dronagiri_data_submission_app_delete($selected_id, $AllowDeleteOfParents = false, $skipChecks = false) {
	// insure referential integrity ...
	global $Translation;
	$selected_id = makeSafe($selected_id);

	// mm: can member delete record?
	if(!check_record_permission('operation_dronagiri_data_submission_app', $selected_id, 'delete')) {
		return $Translation['You don\'t have enough permissions to delete this record'];
	}

	// hook: operation_dronagiri_data_submission_app_before_delete
	if(function_exists('operation_dronagiri_data_submission_app_before_delete')) {
		$args = [];
		if(!operation_dronagiri_data_submission_app_before_delete($selected_id, $skipChecks, getMemberInfo(), $args))
			return $Translation['Couldn\'t delete this record'] . (
				!empty($args['error_message']) ?
					'<div class="text-bold">' . strip_tags($args['error_message']) . '</div>'
					: '' 
			);
	}

	// child table: file_table
	$res = sql("SELECT `data_id` FROM `operation_dronagiri_data_submission_app` WHERE `data_id`='{$selected_id}'", $eo);
	$data_id = db_fetch_row($res);
	$rires = sql("SELECT COUNT(1) FROM `file_table` WHERE `data_str_key`='" . makeSafe($data_id[0]) . "'", $eo);
	$rirow = db_fetch_row($rires);
	$childrenATag = '<a class="alert-link" href="file_table_view.php?filterer_data_str_key=' . urlencode($data_id[0]) . '">%s</a>';
	if($rirow[0] && !$AllowDeleteOfParents && !$skipChecks) {
		$RetMsg = $Translation["couldn't delete"];
		$RetMsg = str_replace('<RelatedRecords>', sprintf($childrenATag, $rirow[0]), $RetMsg);
		$RetMsg = str_replace(['[<TableName>]', '<TableName>'], sprintf($childrenATag, 'file_table'), $RetMsg);
		return $RetMsg;
	} elseif($rirow[0] && $AllowDeleteOfParents && !$skipChecks) {
		$RetMsg = $Translation['confirm delete'];
		$RetMsg = str_replace('<RelatedRecords>', sprintf($childrenATag, $rirow[0]), $RetMsg);
		$RetMsg = str_replace(['[<TableName>]', '<TableName>'], sprintf($childrenATag, 'file_table'), $RetMsg);
		$RetMsg = str_replace('<Delete>', '<input type="button" class="btn btn-danger" value="' . html_attr($Translation['yes']) . '" onClick="window.location = `operation_dronagiri_data_submission_app_view.php?SelectedID=' . urlencode($selected_id) . '&delete_x=1&confirmed=1&csrf_token=' . urlencode(csrf_token(false, true)) . (Request::val('Embedded') ? '&Embedded=1' : '') . '`;">', $RetMsg);
		$RetMsg = str_replace('<Cancel>', '<input type="button" class="btn btn-success" value="' . html_attr($Translation[ 'no']) . '" onClick="window.location = `operation_dronagiri_data_submission_app_view.php?SelectedID=' . urlencode($selected_id) . (Request::val('Embedded') ? '&Embedded=1' : '') . '`;">', $RetMsg);
		return $RetMsg;
	}

	sql("DELETE FROM `operation_dronagiri_data_submission_app` WHERE `data_id`='{$selected_id}'", $eo);

	// hook: operation_dronagiri_data_submission_app_after_delete
	if(function_exists('operation_dronagiri_data_submission_app_after_delete')) {
		$args = [];
		operation_dronagiri_data_submission_app_after_delete($selected_id, getMemberInfo(), $args);
	}

	// mm: delete ownership data
	sql("DELETE FROM `membership_userrecords` WHERE `tableName`='operation_dronagiri_data_submission_app' AND `pkValue`='{$selected_id}'", $eo);
}

function operation_dronagiri_data_submission_app_update(&$selected_id, &$error_message = '') {
