		echo '<a href="" onclick="history.go(-1); return false;">' . $Translation['< back'] . '</a></div>';
		exit;
	}
	// get existing values
	$old_data = getRecord('operation_dronagiri_data_submission_app', $selected_id);
	if(is_array($old_data)) {
		$old_data = array_map('makeSafe', $old_data);
		$old_data['selectedID'] = makeSafe($selected_id);
	}

	$data['selectedID'] = makeSafe($selected_id);

	// hook: operation_dronagiri_data_submission_app_before_update
	if(function_exists('operation_dronagiri_data_submission_app_before_update')) {
		$args = ['old_data' => $old_data];
		if(!operation_dronagiri_data_submission_app_before_update($data, getMemberInfo(), $args)) {
			if(isset($args['error_message'])) $error_message = $args['error_message'];
			return false;
		}
	}

	$set = $data; unset($set['selectedID']);
	foreach ($set as $field => $value) {
		$set[$field] = ($value !== '' && $value !== NULL) ? $value : NULL;
	}

	if(!update(
		'operation_dronagiri_data_submission_app', 
		backtick_keys_once($set), 
		['`data_id`' => $selected_id], 
		$error_message
	)) {
		echo $error_message;
		echo '<a href="operation_dronagiri_data_submission_app_view.php?SelectedID=' . urlencode($selected_id) . "\">{$Translation['< back']}</a>";
		exit;
	}


	update_calc_fields('operation_dronagiri_data_submission_app', $data['selectedID'], calculated_fields()['operation_dronagiri_data_submission_app']);

	// hook: operation_dronagiri_data_submission_app_after_update
	if(function_exists('operation_dronagiri_data_submission_app_after_update')) {
		if($row = getRecord('operation_dronagiri_data_submission_app', $data['selectedID'])) $data = array_map('makeSafe', $row);

		$data['selectedID'] = $data['data_id'];
		$args = ['old_data' => $old_data];
		if(!operation_dronagiri_data_submission_app_after_update($data, getMemberInfo(), $args)) return;
	}

	// mm: update record update timestamp
	set_record_owner('operation_dronagiri_data_submission_app', $selected_id);
